True from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    def runs(values):
        found, start, color = [], None, None
        for i in range(len(values) + 1):
            value = values[i] if i < len(values) else None
            if start is not None and (i == len(values) or value != color):
                found.append((color, list(range(start, i))))
                start = None
            if i < len(values) and start is None and value != bg:
                start, color = i, value
        return found

    candidates = []
    for axis in ("horizontal", "vertical"):
        if axis == "horizontal":
            first, second = g[0], g[-1]
        else:
            first = [g[r][0] for r in range(h)]
            second = [g[r][-1] for r in range(h)]
        for color_a, seg_a in runs(first):
            if len(seg_a) < 2:
                continue
            for color_b, seg_b in runs(second):
                if color_a == color_b and len(seg_a) == len(seg_b):
                    candidates.append((len(seg_a), axis, color_a, seg_a, seg_b))
    if not candidates:
        return g
    _, axis, marker, first_seg, second_seg = max(candidates, key=lambda x: x[0])
    non_marker = Counter(v for row in g for v in row if v != bg and v != marker)
    if not non_marker:
        return g
    ray = non_marker.most_common(1)[0][0]

    if axis == "horizontal":
        # The segments are on the top and bottom edges; list order is left-to-right.
        for i in range(len(first_seg)):
            col_top, col_bottom = first_seg[i], second_seg[i]
            active = any(g[r][col_top] == ray for r in range(1, h-1)) or any(g[r][col_bottom] == ray for r in range(1, h-1))
            if not active:
                continue
            for col, source_row, step in ((col_top, 0, 1), (col_bottom, h-1, -1)):
                cells = [(source_row + step*k, col) for k in range(1, h)]
                target = next((p for p in cells if 0 <= p[0] < h and grid[p[0]][p[1]] == ray), None)
                if target is not None:
                    for r, c in cells:
                        if not 0 <= r < h:
                            break
                        if (r, c) == target:
                            g[r][c] = 4
                            break
                        g[r][c] = ray
                else:
                    for r, c in cells:
                        if not 0 <= r < h:
                            break
                        if g[r][c] != marker:
                            g[r][c] = ray
    else:
        # The segments are on the left and right edges; list order is top-to-bottom.
        for i in range(len(first_seg)):
            row_left, row_right = first_seg[i], second_seg[i]
            active = any(g[row_left][c] == ray for c in range(1, w-1)) or any(g[row_right][c] == ray for c in range(1, w-1))
            if not active:
                continue
            for row, source_col, step in ((row_left, 0, 1), (row_right, w-1, -1)):
                cells = [(row, source_col + step*k) for k in range(1, w)]
                target = next((p for p in cells if 0 <= p[1] < w and grid[p[0]][p[1]] == ray), None)
                if target is not None:
                    for r, c in cells:
                        if not 0 <= c < w:
                            break
                        if (r, c) == target:
                            g[r][c] = 4
                            break
                        g[r][c] = ray
                else:
                    for r, c in cells:
                        if not 0 <= c < w:
                            break
                        if g[r][c] != marker:
                            g[r][c] = ray
    return g

